CREATE VIEW app.subscription_v WITH (security_invoker = true) AS
SELECT t.*,
  (t.end_date - app.today())::numeric(18,0) AS days_to_renewal
FROM app.subscription t;

CREATE VIEW app.subscription_line_v WITH (security_invoker = true) AS
SELECT t.*,
  (SELECT h1.name FROM app.account h1 WHERE h1.id = (SELECT h0.account_id FROM app.subscription h0 WHERE h0.id = t.subscription_id))::varchar(1300) AS account_name
FROM app.subscription_line t;

